  "textarea:not(:disabled)",
  "button:not(:disabled)",
  "a[href]",
  "[contenteditable=true]",
  "[tabindex]:not([tabindex='-1'])",
].join(",");

function firstFocusable(root: Element | null) {
  if (!root) return null;
  const autofocus = root.querySelector<HTMLElement>("[autofocus]");
  if (autofocus) return autofocus;
  for (const el of root.querySelectorAll<HTMLElement>(FOCUSABLE)) {
    if (!el.closest("[inert]") && el.getClientRects().length) return el;
  }
  return null;
}

/** The nearest themed subtree, so the portaled panel keeps its tokens. */
function themeRoot(el: Element | null) {
  const root = el?.closest<HTMLElement>("[data-theme]");
  return root && root !== document.documentElement ? root : undefined;
}

/* ---------- Modal ---------- */

type FocusTarget = RefObject<HTMLElement | null> | (() => HTMLElement | null);

export type ModalProps = {
  open: boolean;
  /** The user asked to close: Escape, a click on the backdrop, or your close button. */
  onDismiss: () => void;
  /** Kept for compatibility. Base UI never closes the dialog on its own, so this isn't called. */
  onForceClose?: () => void;
  /** Where focus goes when it opens. Defaults to the first control inside. */
  initialFocus?: FocusTarget;
  /** The panel grows out of this element, and focus returns to it. Defaults to whatever had focus when it opened. */
  triggerRef?: RefObject<HTMLElement | null>;
  /** Where focus goes on close when the trigger is gone (a deleted row, say). */
  finalFocus?: RefObject<HTMLElement | null>;
  /** "center" when it wasn't opened from anything on screen, like a keyboard shortcut. */
  growFrom?: "trigger" | "center";
  role?: "dialog" | "alertdialog";
  className?: string;
  children: ReactNode;
  "aria-label"?: string;
  "aria-labelledby"?: string;
  "aria-describedby"?: string;
};

/** Base UI's Dialog (or AlertDialog) popup over a backdrop; Escape and backdrop clicks call `onDismiss`. */
export function Modal({
  open,
  onDismiss,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  onForceClose,
  initialFocus,
  triggerRef,
  finalFocus,
  growFrom = "trigger",
  role = "dialog",
  className,
  children,
  ...aria
}: ModalProps) {
  // The element that opened it, read as `open` turns true. This runs before
  // Base UI mounts the popup and moves focus inside, so the focused element is
  // still the one that opened it.
  const [trigger, setTrigger] = useState<HTMLElement | null>(null);
  useLayoutEffect(() => {
    if (!open) return;
    const active = document.activeElement;
    setTrigger(triggerRef?.current ?? (active instanceof HTMLElement && active !== document.body ? active : null));
  }, [open, triggerRef]);

  const latest = useRef({ trigger, growFrom });
  useLayoutEffect(() => {
    latest.current = { trigger, growFrom };
  });

  // Grow out of the trigger's center. The viewport is fixed at 0,0, so the
  // panel's offsets are viewport coordinates, untouched by the starting scale.
  const popupRef = useCallback((popup: HTMLDivElement | null) => {
    if (!popup) return;
    const { trigger: t, growFrom: from } = latest.current;
    // On phones the panel is docked at the bottom (dialog.module.css), so it rises from there.
    const docked = matchMedia("(max-width: 480px)").matches;
    const rect = from === "trigger" && !docked && t?.isConnected ? t.getBoundingClientRect() : null;
    popup.style.transformOrigin =
      rect && (rect.width || rect.height)
        ? `${rect.left + rect.width / 2 - popup.offsetLeft}px ${rect.top + rect.height / 2 - popup.offsetTop}px`
        : docked && from === "trigger"
          ? "50% 100%"
          : "50% 50%";
  }, []);

  const Root = role === "alertdialog" ? BaseAlertDialog.Root : BaseDialog.Root;

  return (
    <Root
      open={open}
      onOpenChange={(next) => {
        // Controlled: the owner decides, so a guard can keep it open.
        if (!next) onDismiss();
      }}
    >
      <BaseDialog.Portal container={themeRoot(trigger)}>
        <BaseDialog.Backdrop className={styles.backdrop} />
        <BaseDialog.Viewport className={styles.viewport}>
          <BaseDialog.Popup
            ref={popupRef}
            className={className ? `${styles.modal} ${className}` : styles.modal}
            initialFocus={() => {
              const el = typeof initialFocus === "function" ? initialFocus() : initialFocus?.current;
              return el ?? true;
            }}
            finalFocus={() => {
              // Back to the trigger, unless it's gone or on its way out (inside
              // something inert, like a row being removed): then finalFocus.
              if (trigger?.isConnected && !trigger.closest("[inert]")) return trigger;
              return finalFocus?.current ?? true;
            }}
            {...aria}
          >
            {children}
          </BaseDialog.Popup>
        </BaseDialog.Viewport>
      </BaseDialog.Portal>
    </Root>
  );
}

/* ---------- Dialog ---------- */

type GuardCopy = {
  title?: string;
  description?: string;
  keep?: string;
  discard?: string;
};

type StepKey = string | number;

export type DialogProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: ReactNode;
  description?: ReactNode;
  /** The body. With `step`, pass a function of the step so the leaving step can still render. */
  children?: ReactNode | ((step: StepKey) => ReactNode);
  /** The current step of a multi-step body. */
  step?: StepKey;
  /** Actions under the body. Put the main action last. */
  footer?: ReactNode;
  /** Unsaved edits: dismissing asks "Discard changes?" first. A function is called on each attempt. */
  dirty?: boolean | (() => boolean);
  guard?: GuardCopy;
  initialFocus?: RefObject<HTMLElement | null>;
  triggerRef?: RefObject<HTMLElement | null>;
  finalFocus?: RefObject<HTMLElement | null>;
  /** Width: sm 420, md 480, lg 640. */
  size?: "sm" | "md" | "lg";
  role?: "dialog" | "alertdialog";
  /** Block Escape, the backdrop and the close button, e.g. while saving. */
  locked?: boolean;
  className?: string;
};

export function Dialog({
  open,
  onOpenChange,
  title,
  description,
  children,
  step,
  footer,
  dirty = false,
  guard,
  initialFocus,
  triggerRef,
  finalFocus,
  size = "md",
  role = "dialog",
  locked = false,
  className,
}: DialogProps) {
  const id = useId();
  const titleId = `${id}-title`;
  const descriptionId = `${id}-description`;
  const guardTitleId = `${id}-guard-title`;
  const guardTextId = `${id}-guard-text`;
  const bodyRef = useRef<HTMLDivElement>(null);
  const footerRef = useRef<HTMLDivElement>(null);
  const keepRef = useRef<HTMLButtonElement>(null);
  const beforeGuard = useRef<HTMLElement | null>(null);
  const [guarding, setGuarding] = useState(false);

  const [shownStep, setShownStep] = useState(step);
  const [leaving, setLeaving] = useState<{ key: StepKey; n: number } | null>(null);
  const [changes, setChanges] = useState(0);
  // Only a change made while open fades; a reset while closed is simply there next time.
  const [fades, setFades] = useState(false);
  if (shownStep !== step) {
    setShownStep(step);
    setChanges(changes + 1);
    setFades(open);
    setLeaving(shownStep !== undefined && open ? { key: shownStep, n: changes } : null);
  }

  const [wasOpen, setWasOpen] = useState(open);
  if (wasOpen !== open) {
    setWasOpen(open);
    if (!open) {
      setGuarding(false);
      setLeaving(null);
      setFades(false);
    }
  }

  // Focus lost with the leaving step goes to the new step, not the page.
  const stepRef = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    if (changes === 0) return;
    const active = document.activeElement;
    const lost = !active || active === document.body || !!active.closest("[inert]");
    if (lost) firstFocusable(stepRef.current)?.focus({ preventScroll: true });
  }, [changes]);

  const render = (key: StepKey | undefined) =>
    typeof children === "function" ? (key === undefined ? null : children(key)) : children;

  useLayoutEffect(() => {
    if (guarding) keepRef.current?.focus();
  }, [guarding]);

  function isDirty() {
    return typeof dirty === "function" ? dirty() : dirty;
  }

  function dismiss() {
    if (locked) return;
    if (guarding) {
      keepEditing();
      return;
    }
    if (isDirty()) {
      const active = document.activeElement;
      beforeGuard.current = active instanceof HTMLElement ? active : null;
      setGuarding(true);
      return;
    }
    onOpenChange(false);
  }

  function keepEditing() {
    // Commit now, so focus moves back in the same task as the guard leaves and
    // Base UI never sees focus fall out of the panel.
    flushSync(() => setGuarding(false));
    const back = beforeGuard.current;
    const target = back?.isConnected && !back.closest("[inert]") ? back : firstFocusable(bodyRef.current);
    target?.focus();
  }

  function discard() {
    setGuarding(false);
    onOpenChange(false);
  }

  return (
    <Modal
      open={open}
      onDismiss={dismiss}
      onForceClose={() => onOpenChange(false)}
      initialFocus={() => initialFocus?.current ?? firstFocusable(bodyRef.current) ?? firstFocusable(footerRef.current)}
      triggerRef={triggerRef}
      finalFocus={finalFocus}
      role={role}
      className={className ? `${styles.dialog} ${className}` : styles.dialog}
      aria-labelledby={titleId}
      aria-describedby={description ? descriptionId : undefined}
    >
      {/* Eases the panel's height when steps, messages or the guard change it. */}
      <AnimatedSize className={styles.sizer}>
        <div className={styles.frame} data-size={size} data-guarding={guarding || undefined}>
          <header className={styles.header} inert={guarding}>
            <div className={styles.heading}>
              <h2 id={titleId} className={styles.title}>
                {title}
              </h2>
              {description && (
                <p id={descriptionId} className={styles.description}>
                  {description}
                </p>
              )}
            </div>
            <Button variant="ghost" size="sm" className={styles.close} aria-label="Close" onClick={dismiss}>
              <Icon name="close" />
            </Button>
          </header>

          {children && (
            <div ref={bodyRef} className={styles.body} inert={guarding}>
              {step === undefined || typeof children !== "function" ? (
                render(step)
              ) : (
                <div className={styles.steps}>
                  {leaving && (
                    <div
                      key={`step-${leaving.n}`}
                      className={styles.stepOut}
                      inert
                      aria-hidden="true"
                      onAnimationEnd={(e) => {
                        if (e.target === e.currentTarget) setLeaving((l) => (l?.n === leaving.n ? null : l));
                      }}
                    >
                      {render(leaving.key)}
                    </div>
                  )}
                  <div
                    key={`step-${changes}`}
                    ref={stepRef}
                    className={fades ? styles.stepIn : undefined}
                  >
                    {render(step)}
                  </div>
                </div>
              )}
            </div>
          )}

          {(footer || guarding) && (
            <div className={styles.footerCell}>
              {footer && (
                <div ref={footerRef} className={styles.footer} inert={guarding} aria-hidden={guarding || undefined}>
                  {footer}
                </div>
              )}
              {guarding && (
                <div
                  className={styles.guard}
                  role="group"
                  aria-labelledby={guardTitleId}
                  aria-describedby={guardTextId}
                >
                  <div className={styles.guardText}>
                    <p id={guardTitleId} className={styles.guardTitle}>
                      {guard?.title ?? "Discard changes?"}
                    </p>
                    <p id={guardTextId} className={styles.guardDescription}>
                      {guard?.description ?? "Your edits haven’t been saved."}
                    </p>
                  </div>
                  <div className={styles.actions}>
                    <Button ref={keepRef} variant="secondary" onClick={keepEditing}>
                      {guard?.keep ?? "Keep editing"}
                    </Button>
                    <Button variant="danger" onClick={discard}>
                      {guard?.discard ?? "Discard"}
                    </Button>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </AnimatedSize>
    </Modal>
  );
}

/** Lays footer buttons out in a row; on phones they wrap. */
export function DialogActions({ children }: { children: ReactNode }) {
  return <div className={styles.actions}>{children}</div>;
}

/* ---------- ConfirmDialog ---------- */

export type ConfirmDialogProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: ReactNode;
  description?: ReactNode;
  /** The verb: "Delete estimate", never "OK". */
  confirmLabel: string;
  cancelLabel?: string;
  /** Return a promise to keep the dialog open, busy, until it settles. A rejection shows its message. */
  onConfirm: () => void | Promise<unknown>;
  tone?: "danger" | "default";
  triggerRef?: RefObject<HTMLElement | null>;
  finalFocus?: RefObject<HTMLElement | null>;
};

export function ConfirmDialog({
  open,
  onOpenChange,
  title,
  description,
  confirmLabel,
  cancelLabel = "Cancel",
  onConfirm,
  tone = "danger",
  triggerRef,
  finalFocus,
}: ConfirmDialogProps) {
  const cancelRef = useRef<HTMLButtonElement>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [wasOpen, setWasOpen] = useState(open);
  if (wasOpen !== open) {
    setWasOpen(open);
    if (open) setError(null);
  }

  async function confirm() {
    setError(null);
    const result = onConfirm();
    if (!(result instanceof Promise)) {
      onOpenChange(false);
      return;
    }
    setBusy(true);
    try {
      await result;
      onOpenChange(false);
    } catch (reason) {
      setError(reason instanceof Error && reason.message ? reason.message : "That didn’t work. Try again.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <Dialog
      open={open}
      onOpenChange={onOpenChange}
      role="alertdialog"
      size="sm"
      title={title}
      description={description}
      locked={busy}
      initialFocus={cancelRef}
      triggerRef={triggerRef}
      finalFocus={finalFocus}
      footer={
        <>
          <p className={styles.error} role="alert">
            {error}
          </p>
          <DialogActions>
            <Button ref={cancelRef} variant="secondary" onClick={() => onOpenChange(false)} disabled={busy}>
              {cancelLabel}
            </Button>
            <Button variant={tone === "danger" ? "danger" : "primary"} busy={busy} onClick={confirm}>
              {confirmLabel}
            </Button>
          </DialogActions>
        </>
      }
    />
  );
}

@layer theme, base, components, utilities;

.text {
  composes: wrap from "../text/text.module.css";
}

.loadingLabel {
  composes: wrap from "../text/text.module.css";
}

.loadingText {
  composes: sweep from "../text/text.module.css";
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  /* Doubled to win over the Modal's own rules, whatever order the sheets load in. */
  .palette.palette {
    --modal-width: 600px;
    --palette-radius: var(--ui-radius-lg);
    --palette-pad: var(--ui-inset-menu);
    --palette-inner-radius: calc(var(--palette-radius) - var(--palette-pad));

    border-radius: var(--palette-radius);
    /* The viewport pads by --ui-space-5 already; this sets the gap from the top of the screen. */
    align-self: start;
    margin-top: calc(min(14dvh, 120px) - var(--ui-space-5));
    max-height: calc(100dvh - min(14dvh, 120px) - var(--ui-space-5));
    display: flex;
    flex-direction: column;
  }

  /* ---------- Search field ---------- */

  .search {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    gap: var(--ui-space-3);
    height: 56px;
    padding-inline: calc(var(--palette-pad) + var(--ui-pad-row));
    /* Not a border: that would add its width and push everything off the grid. */
    box-shadow: inset 0 calc(var(--ui-hairline) * -1) 0 var(--ui-border);
  }

  .searchIcon {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    flex-shrink: 0;
    color: var(--ui-subtle);
  }

  .input {
    flex: 1;
    min-width: 0;
    height: 100%;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    outline: none;
  }

  .input::placeholder {
    color: var(--ui-subtle);
  }

  /* Only the field takes focus; the caret shows where it is. */
  .input:focus-visible {
    outline: none;
  }

  /* ---------- Results ---------- */

  /* Only this box animates its height, so the rows never re-layout per frame. */
  .viewport {
    flex-shrink: 1;
    min-height: 0;
    overflow: clip;
    transition: height var(--ui-dur-glide) var(--ui-ease-glide);
  }

  .viewport[data-instant] {
    transition: none;
  }

  .scroller {
    max-height: min(400px, calc(100dvh - min(14dvh, 120px) - 160px));
    padding: var(--palette-pad);
    overflow-y: auto;
    overscroll-behavior: contain;
    scroll-padding-block: var(--palette-pad);
    scrollbar-width: thin;
    scrollbar-color: var(--ui-border-strong) transparent;
  }

  .scroller:empty {
    padding: 0;
  }

  .listbox:empty {
    display: none;
  }

  .group + .group {
    margin-top: var(--ui-space-2);
  }

  .heading {
    padding: var(--ui-space-2) var(--ui-pad-row) var(--ui-space-1);
    color: var(--ui-subtle);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-sm);
    user-select: none;
  }

  .option {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    display: flex;
    align-items: center;
    gap: var(--ui-space-3);
    min-height: var(--ui-control-md);
    padding: var(--ui-space-2) var(--ui-pad-row);
    border-radius: var(--palette-inner-radius);
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
    cursor: pointer;
    user-select: none;
    scroll-margin-block: var(--ui-space-6);
    transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .option[data-active] {
    background: var(--ui-fill);
    transition-duration: 0s;
  }

  .option:active {
    background: var(--ui-fill-strong);
  }

  .icon {
    display: grid;
    place-items: center;
    flex-shrink: 0;
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    color: var(--ui-muted);
  }

  .icon svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    stroke-width: var(--ui-icon-stroke);
  }

  .option[data-active] .icon {
    color: var(--ui-foreground);
  }

  .label {
    display: flex;
    flex: 1;
    align-items: baseline;
    gap: var(--ui-space-2);
    min-width: 0;
  }

  /* Color only, so the label never changes width. */
  .text[data-dim] {
    color: var(--ui-muted);
  }

  .match {
    background: none;
    color: var(--ui-foreground);
  }

  .hint {
    flex-shrink: 0;
    color: var(--ui-subtle);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
  }

  .shortcut {
    display: flex;
    flex-shrink: 0;
    gap: 2px;
  }

  .key {
    display: inline-grid;
    place-items: center;
    box-sizing: border-box;
    min-width: 20px;
    height: 20px;
    padding-inline: 6px;
    border-radius: min(var(--palette-inner-radius), 10px);
    background: var(--ui-fill);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border);
    color: var(--ui-muted);
    font-family: var(--ui-font-sans);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    font-style: normal;
    line-height: 1;
  }

  /* The shortcut and the Enter key share one cell, at the row's end. The
     highlighted row shows Enter, since that's what runs it now; the others
     show their shortcut. Hidden, not removed, so the cell keeps its width. */
  .keys {
    display: grid;
    flex-shrink: 0;
    justify-items: end;
  }

  .keys > * {
    grid-area: 1 / 1;
  }

  .enter,
  .option[data-active] .shortcut {
    visibility: hidden;
  }

  .option[data-active] .enter {
    visibility: visible;
  }

  /* ---------- Loading, empty, footer ---------- */

  .loading {
    margin-top: var(--ui-space-2);
    animation: fade-in var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .listbox:empty + .loading {
    margin-top: 0;
  }

  .loadingRow {
    display: flex;
    align-items: center;
    gap: var(--ui-space-3);
    min-height: var(--ui-control-md);
    padding-inline: var(--ui-pad-row);
    color: var(--ui-muted);
    font-size: var(--ui-text-md);
  }

  .loadingLabel {
    color: var(--ui-foreground);
  }

  .empty {
    display: grid;
    gap: var(--ui-space-1);
    padding: var(--ui-space-6) var(--ui-space-4);
    text-align: center;
    animation: fade-in var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .emptyTitle {
    margin: 0;
    overflow-wrap: anywhere;
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
  }

  .emptyHint {
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    text-wrap: balance;
  }

  .footer {
    display: flex;
    flex-shrink: 0;
    gap: var(--ui-space-4);
    padding: var(--palette-pad);
    box-shadow: inset 0 var(--ui-hairline) 0 var(--ui-border);
    color: var(--ui-subtle);
    font-size: var(--ui-text-sm);
    line-height: 1;
  }

  .footer span {
    display: inline-flex;
    align-items: center;
    gap: var(--ui-space-1);
  }

  @keyframes fade-in {
    from {
      opacity: 0;
    }
  }

  /* 16px input text so iOS doesn't zoom on focus. */
  @media (pointer: coarse) {
    .option {
      min-height: var(--ui-control-lg);
    }
    .input {
      font-size: var(--ui-text-touch);
    }
    .footer,
    .enter {
      display: none;
    }
    .option[data-active] .shortcut {
      visibility: visible;
    }
  }

  @media (max-width: 480px) {
    /* 8px off the top and sides, like a dialog docked at the bottom on phones. */
    .palette.palette {
      margin-top: calc(var(--ui-space-2) - var(--ui-space-5));
      max-height: calc(100dvh - 2 * var(--ui-space-2));
    }
    .scroller {
      max-height: min(400px, calc(100dvh - 160px));
    }
    .hint {
      display: none;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .viewport {
      transition: none;
    }
    .loading,
    .empty {
      animation: none;
    }
    .loadingLabel {
      color: var(--ui-muted);
    }
  }
}

"use client";

import {
  Fragment,
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
  type RefObject,
} from "react";
import { Modal } from "../dialog/dialog";
import { Icon } from "../icons/icons";
import { fuzzyMatch } from "./fuzzy";
import styles from "./command-palette.module.css";

export type Command = {
  /** Unique across all sources; recents are stored by id. */
  id: string;
  label: string;
  /** Group heading. Groups keep the order they first appear in. */
  group?: string;
  /** Extra search words, e.g. "theme". */
  keywords?: string[];
  hint?: string;
  /** Keys shown on the right, e.g. ["⌘", "N"]. Display only: bind them yourself. */
  shortcut?: string[];
  icon?: ReactNode;
  onSelect: () => void;
};

export type CommandSource = {
  id: string;
  heading: string;
  /** Called after typing pauses. Stop work when `signal` aborts. */
  search: (query: string, signal: AbortSignal) => Promise<Command[]>;
  /** Shown if results take longer than 300ms. */
  loadingLabel?: string;
  /** Don't search until the query is this long. Default 1. */
  minLength?: number;
};

export type CommandPaletteProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  commands: Command[];
  sources?: CommandSource[];
  /** Recent ids, newest first; pair with `onRecentChange`. */
  recent?: string[];
  onRecentChange?: (ids: string[]) => void;
  maxRecent?: number;
  /** ⌘K / Ctrl+K by default. `false` to bind it yourself. */
  hotkey?: string | false;
  placeholder?: string;
  label?: string;
  emptyHint?: string;
  triggerRef?: RefObject<HTMLElement | null>;
};

type Row = { key: string; command: Command; indices: number[] };
type Group = { key: string; heading: string; rows: Row[] };
type SourceState = { status: "idle" | "loading" | "done" | "error"; query: string; items: Command[]; slow: boolean };

const IDLE: SourceState = { status: "idle", query: "", items: [], slow: false };
const LOADING_DELAY = 300;
const DEBOUNCE = 120;

function score(query: string, command: Command) {
  const label = fuzzyMatch(query, command.label);
  if (label) return label;
  let best: number | null = null;
  for (const word of command.keywords ?? []) {
    const m = fuzzyMatch(query, word);
    if (m && (best === null || m.score > best)) best = m.score;
  }
  return best === null ? null : { score: best * 0.6, indices: [] };
}

export function CommandPalette({
  open,
  onOpenChange,
  commands,
  sources = [],
  recent: recentProp,
  onRecentChange,
  maxRecent = 5,
  hotkey = "k",
  placeholder = "Type a command or search…",
  label = "Command palette",
  emptyHint = "Check the spelling, or try fewer letters.",
  triggerRef,
}: CommandPaletteProps) {
  const id = useId();
  const listId = `${id}-list`;
  const inputRef = useRef<HTMLInputElement>(null);
  // State, not a ref: the popup mounts in Base UI's portal after `open` turns true.
  const viewportRef = useRef<HTMLDivElement | null>(null);
  const [viewportMounted, setViewportMounted] = useState(false);
  const attachViewport = useCallback((el: HTMLDivElement | null) => {
    viewportRef.current = el;
    setViewportMounted(!!el);
  }, []);
  const scrollerRef = useRef<HTMLDivElement>(null);
  const scrollToActive = useRef(false);

  const [query, setQuery] = useState("");
  const [activeKey, setActiveKey] = useState<string | null>(null);
  const [localRecent, setLocalRecent] = useState<string[]>([]);
  const [seen, setSeen] = useState<Record<string, Command>>({});
  const [results, setResults] = useState<Record<string, SourceState>>({});
  const recent = recentProp ?? localRecent;

  const [wasOpen, setWasOpen] = useState(open);
  if (wasOpen !== open) {
    setWasOpen(open);
    if (open) {
      setQuery("");
      setActiveKey(null);
      setResults({});
    }
  }

  useEffect(() => {
    if (!hotkey) return;
    function onKey(event: globalThis.KeyboardEvent) {
      if (!(event.metaKey || event.ctrlKey) || event.altKey || event.shiftKey) return;
      if (event.key.toLowerCase() !== hotkey) return;
      event.preventDefault();
      onOpenChange(!open);
    }
    addEventListener("keydown", onKey);
    return () => removeEventListener("keydown", onKey);
  }, [hotkey, open, onOpenChange]);

  const trimmed = query.trim();
  const [retryCount, setRetryCount] = useState(0);
  useEffect(() => {
    if (!open) return;
    const controllers: AbortController[] = [];
    const timers: number[] = [];
    for (const source of sources) {
      if (trimmed.length < (source.minLength ?? 1)) continue;
      const controller = new AbortController();
      controllers.push(controller);
      const set = (patch: Partial<SourceState>) =>
        setResults((r) => ({ ...r, [source.id]: { ...(r[source.id] ?? IDLE), ...patch } }));
      timers.push(
        window.setTimeout(() => {
          set({ status: "loading", query: trimmed, items: [], slow: false });
          timers.push(window.setTimeout(() => set({ slow: true }), LOADING_DELAY - DEBOUNCE));
          source.search(trimmed, controller.signal).then(
            (items) => {
              if (!controller.signal.aborted) set({ status: "done", items, slow: false });
            },
            () => {
              if (!controller.signal.aborted) set({ status: "error", items: [], slow: false });
            },
          );
        }, DEBOUNCE),
      );
    }
    return () => {
      controllers.forEach((c) => c.abort());
      timers.forEach(clearTimeout);
    };
    // `sources` is usually a new array each render; key on ids instead.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, trimmed, retryCount, sources.map((s) => s.id).join()]);

  const groups = useMemo<Group[]>(() => {
    const out: Group[] = [];
    const lookup = new Map<string, Command>(Object.entries(seen));
    for (const c of commands) lookup.set(c.id, c);

    if (!trimmed) {
      const rows = recent
        .map((rid) => lookup.get(rid))
        .filter((c): c is Command => !!c)
        .slice(0, maxRecent)
        .map((command) => ({ key: `recent:${command.id}`, command, indices: [] }));
      if (rows.length) out.push({ key: "recent", heading: "Recent", rows });
      const byGroup = new Map<string, Row[]>();
      for (const command of commands) {
        const g = command.group ?? "Commands";
        if (!byGroup.has(g)) byGroup.set(g, []);
        byGroup.get(g)!.push({ key: `${g}:${command.id}`, command, indices: [] });
      }
      for (const [g, groupRows] of byGroup) out.push({ key: g, heading: g, rows: groupRows });
      return out;
    }

    const scored = new Map<string, { best: number; rows: (Row & { score: number })[] }>();
    for (const command of commands) {
      const m = score(trimmed, command);
      if (!m) continue;
      const g = command.group ?? "Commands";
      if (!scored.has(g)) scored.set(g, { best: -Infinity, rows: [] });
      const entry = scored.get(g)!;
      entry.rows.push({ key: `${g}:${command.id}`, command, indices: m.indices, score: m.score });
      entry.best = Math.max(entry.best, m.score);
    }
    const staticGroups = [...scored.entries()]
      .sort((a, b) => b[1].best - a[1].best)
      .map(([g, entry]) => ({
        key: g,
        heading: g,
        rows: entry.rows.sort((a, b) => b.score - a.score),
      }));
    out.push(...staticGroups);

    // Async results go last, so late arrivals never move what's under the cursor.
    for (const source of sources) {
      const state = results[source.id];
      if (!state || state.query !== trimmed) continue;
      if (state.status === "done" && state.items.length) {
        out.push({
          key: `source:${source.id}`,
          heading: source.heading,
          rows: state.items.map((command) => ({
            key: `${source.id}:${command.id}`,
            command,
            indices: fuzzyMatch(trimmed, command.label)?.indices ?? [],
          })),
        });
      }
      if (state.status === "error") {
        out.push({
          key: `source:${source.id}`,
          heading: source.heading,
          rows: [
            {
              key: `${source.id}:retry`,
              indices: [],
              command: {
                id: `${source.id}:retry`,
                label: `Couldn’t search ${source.heading.toLowerCase()}. Try again`,
                onSelect: () => {
                  setResults((r) => ({ ...r, [source.id]: IDLE }));
                  setRetryCount((n) => n + 1);
                },
              },
            },
          ],
        });
      }
    }
    return out;
  }, [commands, sources, results, recent, seen, trimmed, maxRecent]);

  const rows = groups.flatMap((g) => g.rows);
  const active = rows.find((r) => r.key === activeKey) ?? rows[0] ?? null;
  const optionId = (key: string) => `${id}-opt-${key.replace(/[^\w-]/g, "_")}`;

  const current = (s: CommandSource) => (results[s.id]?.query === trimmed ? results[s.id] : undefined);
  const pending = trimmed ? sources.filter((s) => current(s)?.status === "loading") : [];
  const slow = pending.filter((s) => current(s)?.slow);
  // Debounce pending: not "no results" yet.
  const waiting = sources.some((s) => trimmed.length >= (s.minLength ?? 1) && !current(s));
  const empty = trimmed.length > 0 && rows.length === 0 && pending.length === 0 && !waiting;

  // Only keyboard moves scroll; pointer moves would slide the list under the cursor.
  useLayoutEffect(() => {
    if (!scrollToActive.current || !active) return;
    scrollToActive.current = false;
    document.getElementById(optionId(active.key))?.scrollIntoView({ block: "nearest" });
  });

  // Only the viewport's height animates, so the scroller's rows lay out once per change.
  useLayoutEffect(() => {
    const viewport = viewportRef.current;
    const scroller = scrollerRef.current;
    if (!viewport || !scroller) return;
    viewport.dataset.instant = "";
    viewport.style.height = `${scroller.offsetHeight}px`;
    const frame = requestAnimationFrame(() => delete viewport.dataset.instant);
    const observer = new ResizeObserver(() => {
      viewport.style.height = `${scroller.offsetHeight}px`;
    });
    observer.observe(scroller);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [viewportMounted]);

  function move(to: number) {
    if (!rows.length) return;
    const index = (to + rows.length) % rows.length;
    scrollToActive.current = true;
    setActiveKey(rows[index].key);
  }

  function run(row: Row) {
    const { command } = row;
    if (!command.id.endsWith(":retry")) {
      const next = [command.id, ...recent.filter((r) => r !== command.id)].slice(0, maxRecent);
      if (recentProp === undefined) setLocalRecent(next);
      onRecentChange?.(next);
      if (!commands.some((c) => c.id === command.id)) setSeen((s) => ({ ...s, [command.id]: command }));
      onOpenChange(false);
    }
    command.onSelect();
  }

  function onKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    const index = active ? rows.indexOf(active) : -1;
    if (event.key === "ArrowDown") {
      event.preventDefault();
      move(index + 1);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      move(index - 1);
    } else if (event.key === "Home" && rows.length) {
      event.preventDefault();
      move(0);
    } else if (event.key === "End" && rows.length) {
      event.preventDefault();
      move(rows.length - 1);
    } else if (event.key === "Enter" && !event.nativeEvent.isComposing) {
      event.preventDefault();
      if (active) run(active);
    }
  }

  const status = !trimmed
    ? ""
    : empty
      ? `No results for ${trimmed}`
      : slow.length
        ? `${rows.length} results, searching ${slow.map((s) => s.heading.toLowerCase()).join(", ")}`
        : `${rows.length} ${rows.length === 1 ? "result" : "results"}`;

  // The field keeps focus whatever is pressed inside the palette.
  function keepFocus(event: ReactPointerEvent<HTMLElement>) {
    const target = event.target as HTMLElement;
    if (target === inputRef.current) return;
    // A press on a classic scrollbar keeps working as a drag.
    if (event.nativeEvent.offsetX > target.clientWidth && target.clientWidth > 0) return;
    event.preventDefault();
    if (document.activeElement !== inputRef.current) inputRef.current?.focus({ preventScroll: true });
  }

  return (
    <Modal
      open={open}
      onDismiss={() => onOpenChange(false)}
      initialFocus={inputRef}
      triggerRef={triggerRef}
      growFrom="center"
      className={styles.palette}
      aria-label={label}
    >
      <div className={styles.search} onPointerDown={keepFocus}>
        <Icon className={styles.searchIcon} name="search" />
        <input
          ref={inputRef}
          className={styles.input}
          role="combobox"
          aria-expanded="true"
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={active ? optionId(active.key) : undefined}
          aria-label={label}
          placeholder={placeholder}
          autoComplete="off"
          autoCorrect="off"
          spellCheck={false}
          enterKeyHint="go"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setActiveKey(null);
            scrollerRef.current?.scrollTo({ top: 0 });
          }}
          onKeyDown={onKeyDown}
        />
      </div>

      <div ref={attachViewport} className={styles.viewport} onPointerDown={keepFocus}>
        <div ref={scrollerRef} className={styles.scroller}>
          <div id={listId} role="listbox" aria-label={label} className={styles.listbox}>
            {groups.map((group) => (
              <div key={group.key} role="group" aria-labelledby={`${id}-${group.key}`} className={styles.group}>
                <div id={`${id}-${group.key}`} className={styles.heading} aria-hidden="true">
                  {group.heading}
                </div>
                {group.rows.map((row) => {
                  const selected = row === active;
                  return (
                    <div
                      key={row.key}
                      id={optionId(row.key)}
                      role="option"
                      aria-selected={selected}
                      data-active={selected || undefined}
                      className={styles.option}
                      onPointerDown={(e) => e.preventDefault()}
                      onPointerMove={() => !selected && setActiveKey(row.key)}
                      onClick={() => run(row)}
                    >
                      {row.command.icon && (
                        <span className={styles.icon} aria-hidden="true">
                          {row.command.icon}
                        </span>
                      )}
                      <span className={styles.label}>
                        <Highlight text={row.command.label} indices={row.indices} dim={!!trimmed} />
                        {row.command.hint && <span className={styles.hint}>{row.command.hint}</span>}
                      </span>
                      {/* Enter is on every row and shows on the highlighted one, in the
                          shortcut's place: the cell holds the wider of the two, so moving
                          the highlight never reflows a label. */}
                      <span className={styles.keys} aria-hidden="true">
                        {row.command.shortcut && (
                          <span className={styles.shortcut}>
                            {row.command.shortcut.map((k) => (
                              <kbd key={k} className={styles.key}>
                                {k}
                              </kbd>
                            ))}
                          </span>
                        )}
                        <kbd className={`${styles.key} ${styles.enter}`}>enter</kbd>
                      </span>
                    </div>
                  );
                })}
              </div>
            ))}
          </div>

          {slow.map((source) => (
            <div key={source.id} className={styles.loading}>
              <div className={styles.heading}>{source.heading}</div>
              <div className={styles.loadingRow}>
                <span className={styles.loadingLabel}>
                  <span className={styles.loadingText}>
                    {source.loadingLabel ?? `Searching ${source.heading.toLowerCase()}…`}
                  </span>
                </span>
              </div>
            </div>
          ))}

          {empty && (
            <div className={styles.empty}>
              <p className={styles.emptyTitle}>No results for “{trimmed}”</p>
              <p className={styles.emptyHint}>{emptyHint}</p>
            </div>
          )}
        </div>
      </div>

      <footer className={styles.footer} aria-hidden="true" onPointerDown={keepFocus}>
        <span>
          <kbd className={styles.key}>↑</kbd>
          <kbd className={styles.key}>↓</kbd> to move
        </span>
        <span>
          <kbd className={styles.key}>enter</kbd> to run
        </span>
        <span>
          <kbd className={styles.key}>esc</kbd> to close
        </span>
      </footer>

      <div role="status" className={styles.srOnly}>
        {status}
      </div>
    </Modal>
  );
}

function Highlight({ text, indices, dim }: { text: string; indices: number[]; dim: boolean }) {
  if (!dim) return <span className={styles.text}>{text}</span>;
  const hit = new Set(indices);
  const parts: { text: string; match: boolean }[] = [];
  for (let i = 0; i < text.length; i++) {
    const match = hit.has(i);
    const last = parts[parts.length - 1];
    if (last && last.match === match) last.text += text[i];
    else parts.push({ text: text[i], match });
  }
  return (
    <span className={styles.text} data-dim="">
      {parts.map((p, i) =>
        p.match ? (
          <mark key={i} className={styles.match}>
            {p.text}
          </mark>
        ) : (
          <Fragment key={i}>{p.text}</Fragment>
        ),
      )}
    </span>
  );
}

/** Fuzzy subsequence match that finds the best-scoring placement, not the first. */

export type FuzzyMatch = { score: number; indices: number[] };

const MATCH = 1;
const WORD_START = 8;
const PREFIX = 6;
const CONSECUTIVE = 8;
const GAP = 0.5;
const LEADING_GAP = 0.15;

function isWordStart(text: string, i: number) {
  if (i === 0) return true;
  const prev = text[i - 1];
  const cur = text[i];
  if (/[\s\-_/.,:()]/.test(prev)) return true;
  // camelCase and letter → digit boundaries
  if (prev === prev.toLowerCase() && cur !== cur.toLowerCase()) return true;
  return /\D/.test(prev) && /\d/.test(cur);
}

export function fuzzyMatch(query: string, text: string): FuzzyMatch | null {
  const q = query.trim().toLowerCase().replace(/\s+/g, " ");
  if (!q) return { score: 0, indices: [] };
  const t = text.toLowerCase();
  const n = q.length;
  const m = t.length;
  if (n > m) return null;

  for (let i = 0, j = 0; i < n; i++, j++) {
    while (j < m && t[j] !== q[i]) j++;
    if (j === m) return null;
  }

  const bonus = new Float64Array(m);
  for (let j = 0; j < m; j++) bonus[j] = MATCH + (isWordStart(text, j) ? WORD_START : 0) + (j === 0 ? PREFIX : 0);

  // score[i][j]: best score with q[i] matched at t[j]. from[i][j]: where q[i-1] matched.
  const NEG = -Infinity;
  const score: Float64Array[] = [];
  const from: Int32Array[] = [];
  for (let i = 0; i < n; i++) {
    const row = new Float64Array(m).fill(NEG);
    const back = new Int32Array(m).fill(-1);
    // Running best of (score[i-1][k] + GAP * k), k <= j - 2, so a gap costs O(1).
    let best = NEG;
    let bestK = -1;
    for (let j = i; j < m; j++) {
      if (i > 0 && j >= 2) {
        const k = j - 2;
        const candidate = score[i - 1][k] + GAP * k;
        if (candidate > best) {
          best = candidate;
          bestK = k;
        }
      }
      if (t[j] !== q[i]) continue;
      if (i === 0) {
        row[j] = bonus[j] - LEADING_GAP * j;
        continue;
      }
      const adjacent = score[i - 1][j - 1] + CONSECUTIVE;
      const gapped = best - GAP * (j - 1);
      if (adjacent >= gapped && adjacent > NEG) {
        row[j] = adjacent + bonus[j];
        back[j] = j - 1;
      } else if (gapped > NEG) {
        row[j] = gapped + bonus[j];
        back[j] = bestK;
      }
    }
    score.push(row);
    from.push(back);
  }

  let end = -1;
  let top = NEG;
  for (let j = 0; j < m; j++) {
    if (score[n - 1][j] > top) {
      top = score[n - 1][j];
      end = j;
    }
  }
  if (end < 0) return null;

  const indices = new Array<number>(n);
  for (let i = n - 1, j = end; i >= 0; i--) {
    indices[i] = j;
    j = from[i][j];
  }
  // Shorter labels win ties.
  return { score: top - (m - n) * 0.01, indices };
}
